    def load_logo(self, parent):
        """يستخرج الشعار المضمّن إلى ملف مؤقت ثم يعرضه بواسطة Tkinter مباشرة."""
        try:
            logo_path = os.path.join(tempfile.gettempdir(), "maktabat_alamal_logo_runtime.png")
            with open(logo_path, "wb") as f:
                f.write(base64.b64decode(LOGO_BASE64))

            self.logo_runtime_path = logo_path
            image = tk.PhotoImage(file=logo_path)

            # الصورة 256×256، نعرضها بحجم يقارب 80×80.
            ratio = max(1, image.width() // 80)
            self.logo_image = image.subsample(ratio, ratio)

            tk.Label(
                parent,
                image=self.logo_image,
                bg=PRIMARY_DARK,
                bd=0,
                highlightthickness=0
            ).pack(expand=True)

            self.app_icon = self.logo_image
            try:
                self.root.iconphoto(False, self.app_icon)
            except Exception:
                pass
        except Exception as exc:
            # في حال وجود مشكلة نعرض اسم المكتبة، لكن البرنامج يستمر بالعمل.
            tk.Label(
                parent,
                text="مكتبة\nالأمل",
                bg=PRIMARY,
                fg=WHITE,
                font=("Segoe UI", 12, "bold"),
                width=8,
                height=3,
                relief="flat"
            ).pack(expand=True)


