    def make_nav_button(self, icon, text, command):
        key = text
        btn = tk.Button(
            self.sidebar,
            text=f"{icon}   {text}",
            command=command,
            bg=DARK,
            fg=WHITE,
            activebackground=HOVER,
            activeforeground=WHITE,
            relief="flat",
            bd=0,
            font=("Segoe UI", 11, "bold"),
            anchor="e",
            padx=18,
            pady=13,
            cursor="hand2",
            highlightthickness=0
        )
        btn.pack(fill="x", padx=10, pady=3)
        self.nav_buttons[key] = btn

        btn.bind("<Enter>", lambda e, b=btn: b.configure(bg=HOVER if b is not self.active_nav_button else PRIMARY))
        btn.bind("<Leave>", lambda e, b=btn: b.configure(bg=PRIMARY if b is getattr(self, "active_nav_button", None) else DARK))

        return btn


    def set_active_nav(self, key):
        self.active_nav_button = self.nav_buttons.get(key)
        for name, button in self.nav_buttons.items():
            if button is self.active_nav_button:
                button.configure(bg=PRIMARY)
            else:
                button.configure(bg=DARK)


    def on_close(self):
        try:
            conn.commit()
            conn.close()
        except Exception:
            pass
        self.root.destroy()


