    # ========================================================
    # تحميل المنتجات للكاشير
    # ========================================================

    def load_pos_products(self):

        for item in self.pos_tree.get_children():
            self.pos_tree.delete(item)

        search = ""

        if hasattr(self, "search_entry"):
            search = self.search_entry.get().strip()

        if search:

            cursor.execute("""
                SELECT id, name, barcode, price, stock
                FROM products
                WHERE name LIKE ?
                OR barcode LIKE ?
                ORDER BY name
            """, (f"%{search}%", f"%{search}%"))

        else:

            cursor.execute("""
                SELECT id, name, barcode, price, stock
                FROM products
                ORDER BY name
            """)

        rows = cursor.fetchall()

        for row in rows:

            self.pos_tree.insert(
                "",
                "end",
                values=(
                    row[0],
                    row[1],
                    row[2] or "",
                    f"{row[3]:.3f}",
                    row[4]
                )
            )


    # ========================================================
    # إضافة منتج للسلة
    # ========================================================

    def add_selected_product(self):

        selected = self.pos_tree.selection()

        if not selected:
            messagebox.showwarning(
                "تنبيه",
                "اختر منتجًا أولاً."
            )
            return

        item = self.pos_tree.item(selected[0])

        product_id = item["values"][0]

        cursor.execute(
            "SELECT id, name, price, stock FROM products WHERE id=?",
            (product_id,)
        )

        product = cursor.fetchone()

        if not product:
            return

        pid, name, price, stock = product

        if stock <= 0:
            messagebox.showwarning(
                "المخزون",
                "هذا المنتج غير متوفر في المخزون."
            )
            return

        for cart_item in self.cart:

            if cart_item["id"] == pid:

                if cart_item["quantity"] + 1 > stock:

                    messagebox.showwarning(
                        "المخزون",
                        "الكمية المطلوبة أكبر من المخزون."
                    )

                    return

                cart_item["quantity"] += 1
                self.refresh_cart()
                return

        self.cart.append({
            "id": pid,
            "name": name,
            "price": price,
            "quantity": 1,
            "stock": stock
        })

        self.refresh_cart()


    # ========================================================
    # إضافة بالباركود
    # ========================================================

    def add_by_barcode(self):

        barcode = self.search_entry.get().strip()

        if not barcode:
            return

        cursor.execute("""
            SELECT id, name, price, stock
            FROM products
            WHERE barcode=?
        """, (barcode,))

        product = cursor.fetchone()

        if not product:

            messagebox.showwarning(
                "الباركود",
                "لم يتم العثور على المنتج."
            )

            return

        pid, name, price, stock = product

        if stock <= 0:

            messagebox.showwarning(
                "المخزون",
                "المنتج غير متوفر."
            )

            return

        for item in self.cart:

            if item["id"] == pid:

                if item["quantity"] < stock:
                    item["quantity"] += 1

                self.refresh_cart()
                return

        self.cart.append({
            "id": pid,
            "name": name,
            "price": price,
            "quantity": 1,
            "stock": stock
        })

        self.refresh_cart()


    # ========================================================
    # تحديث السلة
    # ========================================================

    def refresh_cart(self):

        for item in self.cart_tree.get_children():
            self.cart_tree.delete(item)

        total = 0

        for item in self.cart:

            subtotal = (
                item["price"] *
                item["quantity"]
            )

            total += subtotal

            self.cart_tree.insert(
                "",
                "end",
                iid=str(item["id"]),
                values=(
                    item["name"],
                    item["quantity"],
                    f"{item['price']:.3f}",
                    f"{subtotal:.3f}"
                )
            )

        self.total_label.config(
            text=f"الإجمالي: {total:.3f} {CURRENCY}"
        )

        self.calculate_change()


    # ========================================================
    # حساب الباقي
    # ========================================================

    def calculate_change(self, event=None):

        total = sum(
            item["price"] * item["quantity"]
            for item in self.cart
        )

        try:
            paid = float(
                self.paid_entry.get()
                .replace(",", ".")
            )
        except:
            paid = 0

        change = paid - total

        if change >= 0:

            self.change_label.config(
                text=f"الباقي: {change:.3f} {CURRENCY}",
                fg=GREEN
            )

        else:

            self.change_label.config(
                text=f"المتبقي: {abs(change):.3f} {CURRENCY}",
                fg=RED
            )


    # ========================================================
    # حذف من السلة
    # ========================================================

    def remove_cart_item(self):

        selected = self.cart_tree.selection()

        if not selected:
            return

        product_id = int(selected[0])

        self.cart = [
            item for item in self.cart
            if item["id"] != product_id
        ]

        self.refresh_cart()


    # ========================================================
    # تفريغ السلة
    # ========================================================

    def clear_cart(self):

        self.cart.clear()

        self.refresh_cart()


    # ========================================================
    # إتمام البيع
    # ========================================================

    def complete_sale(self):

        if not self.cart:

            messagebox.showwarning(
                "الفاتورة",
                "السلة فارغة."
            )

            return

        total = sum(
            item["price"] * item["quantity"]
            for item in self.cart
        )

        try:

            paid = float(
                self.paid_entry.get()
                .replace(",", ".")
            )

        except:

            messagebox.showwarning(
                "المبلغ",
                "أدخل المبلغ المدفوع بشكل صحيح."
            )

            return

        if paid < total:

            messagebox.showwarning(
                "المبلغ",
                "المبلغ المدفوع أقل من إجمالي الفاتورة."
            )

            return

        change = paid - total

        date = datetime.now().strftime(
            "%Y-%m-%d %H:%M:%S"
        )

        cursor.execute("""
            INSERT INTO sales
            (sale_date, total, paid, change_amount)
            VALUES (?, ?, ?, ?)
        """, (
            date,
            total,
            paid,
            change
        ))

        sale_id = cursor.lastrowid

        for item in self.cart:

            subtotal = (
                item["price"] *
                item["quantity"]
            )

            cursor.execute("""
                INSERT INTO sale_items
                (
                    sale_id,
                    product_id,
                    product_name,
                    quantity,
                    price,
                    subtotal
                )
                VALUES (?, ?, ?, ?, ?, ?)
            """, (
                sale_id,
                item["id"],
                item["name"],
                item["quantity"],
                item["price"],
                subtotal
            ))

            cursor.execute("""
                UPDATE products
                SET stock = stock - ?
                WHERE id=?
            """, (
                item["quantity"],
                item["id"]
            ))

        conn.commit()

        messagebox.showinfo(
            "تم البيع",
            f"تم تسجيل الفاتورة بنجاح.\n\n"
            f"الإجمالي: {total:.3f} {CURRENCY}\n"
            f"المدفوع: {paid:.3f} {CURRENCY}\n"
            f"الباقي: {change:.3f} {CURRENCY}"
        )

        self.cart.clear()
        self.paid_entry.delete(0, "end")
        self.refresh_cart()
        self.load_pos_products()


