    # ========================================================
    # إضافة منتج
    # ========================================================

    def add_product(self):

        name = self.product_name.get().strip()
        barcode = self.product_barcode.get().strip()

        try:
            price = float(
                self.product_price.get()
                .replace(",", ".")
            )

            stock = int(
                self.product_stock.get()
            )

            min_stock = int(
                self.product_min_stock.get()
                or 5
            )

        except:

            messagebox.showerror(
                "خطأ",
                "تأكد من إدخال السعر والكميات بشكل صحيح."
            )

            return


        if not name:

            messagebox.showwarning(
                "المنتج",
                "أدخل اسم المنتج."
            )

            return


        try:

            cursor.execute("""
                INSERT INTO products
                (
                    name,
                    barcode,
                    price,
                    stock,
                    min_stock,
                    image
                )
                VALUES (?, ?, ?, ?, ?, ?)
            """, (
                name,
                barcode or None,
                price,
                stock,
                min_stock,
                self.selected_image
            ))

            conn.commit()

        except sqlite3.IntegrityError:

            messagebox.showerror(
                "خطأ",
                "هذا الباركود موجود مسبقًا."
            )

            return


        messagebox.showinfo(
            "تم",
            "تمت إضافة المنتج بنجاح."
        )

        self.product_name.delete(0, "end")
        self.product_barcode.delete(0, "end")
        self.product_price.delete(0, "end")
        self.product_stock.delete(0, "end")
        self.product_min_stock.delete(0, "end")

        self.selected_image = ""

        self.load_products()


    # ========================================================
    # تحميل المنتجات
    # ========================================================

    def load_products(self):

        if not hasattr(self, "products_tree"):
            return

        for item in self.products_tree.get_children():
            self.products_tree.delete(item)

        cursor.execute("""
            SELECT
                id,
                name,
                barcode,
                price,
                stock,
                min_stock,
                image
            FROM products
            ORDER BY id DESC
        """)

        for row in cursor.fetchall():

            self.products_tree.insert(
                "",
                "end",
                values=(
                    row[0],
                    row[1],
                    row[2] or "",
                    f"{row[3]:.3f}",
                    row[4],
                    row[5],
                    os.path.basename(row[6])
                    if row[6]
                    else ""
                )
            )


    # ========================================================
    # حذف منتج
    # ========================================================

    def delete_product(self):

        selected = self.products_tree.selection()

        if not selected:
            messagebox.showwarning(
                "حذف",
                "اختر المنتج أولاً."
            )

            return

        item = self.products_tree.item(
            selected[0]
        )

        product_id = item["values"][0]

        confirm = messagebox.askyesno(
            "تأكيد",
            "هل تريد حذف المنتج؟"
        )

        if not confirm:
            return

        cursor.execute(
            "DELETE FROM products WHERE id=?",
            (product_id,)
        )

        conn.commit()

        self.load_products()


    # ========================================================
    # تعديل المنتج
    # ========================================================

    def edit_product_dialog(self, event=None):

        selected = self.products_tree.selection()

        if not selected:
            return

        item = self.products_tree.item(
            selected[0]
        )

        product_id = item["values"][0]

        cursor.execute("""
            SELECT
                name,
                barcode,
                price,
                stock,
                min_stock
            FROM products
            WHERE id=?
        """, (product_id,))

        product = cursor.fetchone()

        if not product:
            return


        dialog = tk.Toplevel(
            self.root
        )

        dialog.title("تعديل المنتج")
        dialog.geometry("420x400")
        dialog.configure(bg=WHITE)

        entries = {}

        labels = [
            ("اسم المنتج", product[0]),
            ("الباركود", product[1] or ""),
            ("السعر", product[2]),
            ("المخزون", product[3]),
            ("حد التنبيه", product[4])
        ]

        for label, value in labels:

            frame = tk.Frame(
                dialog,
                bg=WHITE
            )

            frame.pack(
                fill="x",
                padx=30,
                pady=8
            )

            tk.Label(
                frame,
                text=label,
                bg=WHITE,
                font=("Segoe UI", 10, "bold")
            ).pack(
                side="right"
            )

            entry = ttk.Entry(
                frame,
                justify="right"
            )

            entry.insert(
                0,
                str(value)
            )

            entry.pack(
                side="left",
                fill="x",
                expand=True,
                padx=10
            )

            entries[label] = entry


        def save():

            try:

                name = entries["اسم المنتج"].get()
                barcode = entries["الباركود"].get()
                price = float(
                    entries["السعر"].get()
                )
                stock = int(
                    entries["المخزون"].get()
                )
                min_stock = int(
                    entries["حد التنبيه"].get()
                )

                cursor.execute("""
                    UPDATE products
                    SET
                        name=?,
                        barcode=?,
                        price=?,
                        stock=?,
                        min_stock=?
                    WHERE id=?
                """, (
                    name,
                    barcode or None,
                    price,
                    stock,
                    min_stock,
                    product_id
                ))

                conn.commit()

                dialog.destroy()
                self.load_products()

            except Exception as e:

                messagebox.showerror(
                    "خطأ",
                    f"تعذر حفظ التعديل:\n{e}"
                )


        ttk.Button(
            dialog,
            text="حفظ التعديلات",
            command=save
        ).pack(
            pady=20
        )


